		     CDNS_MCP_CONFIG_OP,
		     CDNS_MCP_CONFIG_OP_NORMAL);

	/* commit changes */
	return cdns_update_config(cdns);
}
EXPORT_SYMBOL(sdw_cdns_exit_reset);

